let verifier=load("verifierOld").replace('if(r.action==="choose_opponent" && moves.length!==0)throw Error("Selection after play");','if(r.action==="choose_opponent"){if(moves.length!==0)throw Error("Selection after play");const opening=s.match(/It plays first: ([A-HJ][1-9])\\./);if(!opening)throw Error("Missing Black opening");apply("X",opening[1]);}');
verifier=verifier.replace('apply("X",r.move)','apply("O",r.move)').replace('if(other)apply("O",other[1]);else if(s.includes("Your opponent passed."))apply("O","pass")','if(other)apply("X",other[1]);else if(s.includes("Your opponent passed."))apply("X","pass")');
store("verifier",verifier);
const verified=eval("("+verifier.trim()+")")(load("records"));store("verified",verified);
text(verified);
const inspect=eval("("+load("inspector").trim()+")")();store("finalInspection",inspect);
const score={X:inspect.groups.filter(g=>g.color==="X").reduce((n,g)=>n+g.stones.length,0),O:inspect.groups.filter(g=>g.color==="O").reduce((n,g)=>n+g.stones.length,0),neutral:0};
for (const room of inspect.rooms){if(room.borders.length===1)score[room.borders[0]]+=room.points.length;else score.neutral+=room.points.length;}
store("score",score);text(score);
const sgf="(;GM[1]FF[4]SZ[9]KM[7]RU[Chinese]PB[KataGo 20k]PW[Codex]RE[B+32]DT[2026-10-07]"+verified.moves.map(m=>";"+(m.color==="X"?"B":"W")+"["+(m.move==="pass"?"":String.fromCharCode(97+"ABCDEFGHJ".indexOf(m.move[0]))+String.fromCharCode(97+9-Number(m.move[1])))+"]").join("")+")\n";
const files={"game-198-log.json":JSON.stringify({game:198,rank:"20k",color:"White",result:"B+32",records:load("records")},null,2),"game-198.sgf":sgf,"game-198-inspection.js":load("inspector"),"game-198-verifier.js":verifier,"game-198-verification.json":JSON.stringify(verified,null,2),"game-198-final-inspection.json":JSON.stringify(inspect,null,2),"game-198-score-inspection.json":JSON.stringify(score,null,2)};
for(const[path,data]of Object.entries(files)){text(await tools.apply_patch("*** Begin Patch\n*** Add File: "+path+"\n"+data.trimEnd().split("\n").map(l=>"+"+l).join("\n")+"\n*** End Patch"));}

